CREATE TABLE app_user (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, email VARCHAR(255) NOT NULL UNIQUE, name VARCHAR(255), password_hash VARCHAR(255), role VARCHAR(255));
CREATE TABLE app_session (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, token_hash VARCHAR(64) NOT NULL UNIQUE, user_id BIGINT NOT NULL, expires_at DATETIME(6) NOT NULL);
CREATE TABLE trip (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, traveler VARCHAR(255), traveler_email VARCHAR(255), lifecycle VARCHAR(255), origin VARCHAR(255), destination VARCHAR(255), origin_airport_code VARCHAR(255), destination_airport_code VARCHAR(255), start_date DATE, end_date DATE, check_in_status VARCHAR(255), checked_in_at DATETIME(6), check_in_note VARCHAR(255));
CREATE TABLE trip_item (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, trip_id BIGINT NOT NULL, kind VARCHAR(255), title VARCHAR(255), location VARCHAR(255), starts_at DATETIME(6), ends_at DATETIME(6), status VARCHAR(255), change_note VARCHAR(255), disruption_type VARCHAR(255), risk_source_item_id BIGINT, replaces_item_id BIGINT, flight_source VARCHAR(255), flight_offer_id VARCHAR(255), flight_amount VARCHAR(255), flight_currency VARCHAR(255), flight_expires_at VARCHAR(255), flight_origin_time_zone VARCHAR(255), flight_destination_time_zone VARCHAR(255), flight_duration_minutes INT, flight_stops INT, flight_operating_carriers VARCHAR(255), flight_route_json TEXT, recovery_search_id VARCHAR(255), CONSTRAINT fk_trip_item_trip FOREIGN KEY (trip_id) REFERENCES trip(id));
CREATE TABLE alternative (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, kind VARCHAR(255), title VARCHAR(255), location VARCHAR(255), delay_minutes INT NOT NULL, estimated_cost DECIMAL(38,2), description VARCHAR(255), source VARCHAR(255), currency VARCHAR(255), flight_offer_id VARCHAR(255), flight_expires_at VARCHAR(255), flight_origin_time_zone VARCHAR(255), flight_destination_time_zone VARCHAR(255), arrival_delay_minutes INT, cost_difference DECIMAL(38,2), flight_stops INT, flight_duration_minutes INT, flight_operating_carriers VARCHAR(255), flight_route_json TEXT, recovery_search_id VARCHAR(255), trip_id BIGINT, item_id BIGINT, starts_at DATETIME(6), ends_at DATETIME(6));
CREATE TABLE trip_event (id BIGINT NOT NULL AUTO_INCREMENT PRIMARY KEY, trip_id BIGINT, item_id BIGINT, type VARCHAR(255), details VARCHAR(1000), occurred_at DATETIME(6));
